using System;using System.Collections;using System.Collections.Generic;using System.IO;using NUnit.Framework;using UnityEngine;using UnityEngine.TestTools;
public sealed partial class FlightMeasurementPlayMode {
 [Serializable]public class R14Sample{public float time,distance,remaining;public Vector3 position,velocity;public int boostCount,actualBreakCount;}
 [Serializable]public class R14Trial{public string id,launch,final,contactTrace;public List<R14Sample> samples=new List<R14Sample>();public List<BreakRecord> actualBreaks=new List<BreakRecord>();}
 [Serializable]public class R14Report{public string state="RUNNING",revision="r14-roof-route1",method="Natural initialization,601 active charge ticks, Tick1/60. No teleport, stock/physics/threshold change; actualBreaks/destructionEvent and boostCount explicitly distinct.";public List<R14Trial> trials=new List<R14Trial>();}
 [UnityTest]public IEnumerator R14RoofRoute(){Directory.CreateDirectory(Evidence);var report=new R14Report();string file=Path.Combine(Evidence,"roof-route.json");Assert.That(File.Exists(file),Is.False);Action save=()=>File.WriteAllText(file,JsonUtility.ToJson(report,true));save();
 foreach(var spec in Environment.GetEnvironmentVariable("CRAB_EVIDENCE_SCOPE")=="compare02"?new[]{new R12Spec{id="r14-final-standard12",angle=12,level=0,rate=2},new R12Spec{id="r14-neighbor16",angle=16,level=0,rate=2}}:new[]{new R12Spec{id="r14-standard12",angle=12,level=0,rate=2},new R12Spec{id="r14-strong35-underpass",angle=35}}){yield return NewRetrySubject(false,true,true,true,true,true,true);StartRouteChargeR11(spec.angle,spec.level,spec.rate,spec.direction);var sim=Property(current,"ReviewSimulation");var row=new R14Trial{id=spec.id,launch=JsonUtility.ToJson(Field(State(current),"launchReceipt"))};report.trials.Add(row);float next=0;bool approach=false,hit=false,after=false;int afterTick=-1;
 for(int tick=0;tick<11000&&!(bool)Property(current,"Finished");tick++){Call(current,"Tick",1f/60);var s=State(current);float dist=F(s,"distance"),time=F(s,"time");if(dist>1020&&dist<1200&&time>=next){var body=(Rigidbody)Property(sim,"Body");row.samples.Add(new R14Sample{time=time,distance=dist,position=body.position,velocity=body.linearVelocity,remaining=F(s,"rotorRemaining"),boostCount=Convert.ToInt32(Field(s,"burstCount")),actualBreakCount=Convert.ToInt32(Field(s,"destructionEvent"))});next=time+.125f;}if(!approach&&dist>1045){CaptureRoute(spec.id,"approach");approach=true;}if(!hit){foreach(var e in (IEnumerable)Field(sim,"BreakEvents")){if(((string)Field(e,"id")).StartsWith("r14-",StringComparison.Ordinal)){CaptureRoute(spec.id,"roof-contact");hit=true;afterTick=tick+12;break;}}}if(hit&&!after&&tick>=afterTick){CaptureRoute(spec.id,"after-contact");after=true;}}
 row.final=JsonUtility.ToJson(State(current));foreach(var e in (IEnumerable)Field(sim,"BreakEvents"))row.actualBreaks.Add(new BreakRecord{id=(string)Field(e,"id"),material=(string)Field(e,"material"),secondary=(bool)Field(e,"secondary"),time=F(e,"time"),position=(Vector3)Field(e,"position")});row.contactTrace=(string)Call(sim,"ReviewContactTraceJson");CaptureRoute(spec.id,"result");save();Assert.That((bool)Property(current,"Finished"),Is.True);Assert.That((string)Field(State(current),"physicsFault"),Is.Empty);if(spec.level==0){Call(current,"RetryLaunch","");Assert.That(Convert.ToInt32(Field(State(current),"destructionEvent")),Is.EqualTo(0));Assert.That(Convert.ToInt32(Field(State(current),"rechargeCount")),Is.EqualTo(0));}Call(current,"ShutdownReviewPhysics");current=null;yield return null;yield return null;}
 report.state="COMPLETED";save();}

 [UnityTest]public IEnumerator R14NeighborControl(){Directory.CreateDirectory(Evidence);var f=cityType.GetField("routeR12",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic);string source=Environment.GetEnvironmentVariable("CRAB_REFERENCE_LAYOUT");Assert.That(File.Exists(source),Is.True);f.SetValue(null,JsonUtility.FromJson(File.ReadAllText(source),f.FieldType));yield return NewRetrySubject(false,true,true,true,true,true,true);StartRouteChargeR11(16,0,2,1);var sim=Property(current,"ReviewSimulation");var report=new R14Report{revision="r14-code-r13-layout-neighbor-control"};var row=new R14Trial{id="r13-layout-neighbor16-control",launch=JsonUtility.ToJson(Field(State(current),"launchReceipt"))};report.trials.Add(row);for(int tick=0;tick<11000&&!(bool)Property(current,"Finished");tick++)Call(current,"Tick",1f/60);row.final=JsonUtility.ToJson(State(current));foreach(var e in (IEnumerable)Field(sim,"BreakEvents"))row.actualBreaks.Add(new BreakRecord{id=(string)Field(e,"id"),material=(string)Field(e,"material"),secondary=(bool)Field(e,"secondary"),time=F(e,"time"),position=(Vector3)Field(e,"position")});row.contactTrace=(string)Call(sim,"ReviewContactTraceJson");CaptureRoute(row.id,"result");Assert.That((bool)Property(current,"Finished"),Is.True);report.state="OBSERVATION_COMPLETE_NOT_GAMEPLAY_PASS";File.WriteAllText(Path.Combine(Evidence,"roof-route.json"),JsonUtility.ToJson(report,true));Call(current,"ShutdownReviewPhysics");current=null;f.SetValue(null,null);yield return null;
 }
}
